from pathlib import Path
import json
P=Path(__file__).parent;S=json.loads((P/'summary.json').read_text());M=json.loads((P/'model/qa.json').read_text());R=(P/'report.md').read_text();H=(P/'report.html').read_text()
checks={'model':M['passed'],'all_current_value_fields_null':all(S[k] is None for k in ['fairValue','fairValueTotal','bear','base','bull','conditionalDcfCases','ownerFCF','certifiedEquityBridge','scenarioEconomicsOnly']),'no_entry_or_completion':all(S[k] is False for k in ['entryApproved','stage3Complete','stage35Complete','latestCompletedEligible']),'history_preserved':S['retainHistoricalDocuments'] and S['historicalStage3Complete'] and not S['historicalValuesAreCurrent'],'timing_disclosed':'no equivalen exactamente a los años naturales' in R,'leases_disclosed':'incluye o excluye' in R,'not_current_value':'no son una banda de valor razonable' in R,'margin_date_not_guidance':'no un compromiso' in R,'html_selfcontained':'<script' not in H and '<title>' in H,'report_length':len(R.split())>1800}
(P/'qa.json').write_text(json.dumps({'passed':all(checks.values()),'checks':checks},indent=2,sort_keys=True)+'\n');assert all(checks.values()),checks;print('QA',checks)
